    public UserId                       frmUserId;
    public HcmWorkerRecId               frmHcmWorkerRecId;
    public HCMWorker                    frmHCMWorker;
    public AVAWorkerInventSite          frmAVAWorkerInventSite;

    public Args                         frmArgs;
    public SalesId                      frmSalesId;
    public SalesTable                   frmSalesTable;
    public SalesLine                    frmSalesLine;

    public boolean                      frmReleaseForShipmentMode;
    public AVASalesLineBackOrderTmp     frmAVASalesLineBackOrderTmp;
    public boolean                      frmShipmentDateConfirmedOverwrite;
    public SalesShippingDateConfirmed   frmShipmentDateConfirmed;
    public boolean                      frmReleaseForShipmentSaveWhenClosing;

    public AVAStockAvailability         frmAVAStockAvailability;

    public boolean                      frmApprovalUnmarkUnreserveSelected; // 6 - ApprovalUnreserveSelected    - Selected in Grid
    public boolean                      frmApprovalReserveSelected;         // 5 - ApprovalReserveSelected      - Selected in Grid
    public boolean                      frmApprovalMarkAvailable;           // 2 - ApprovalMarkAvailable        - AVAStockAvailability::Available           - green, mark all
                                                                            //                                  - AVAStockAvailability::IndividualRequired  - blue, mark all
    public boolean                      frmReleaseFunctionsShippingDate;
    public boolean                      frmReleaseFunctionsReservations;
