/// <summary>
///    AVA <c>registerDatasourceOnQueryingEvent</c> method.
/// </summary>
public void registerDatasourceOnQueryingEvent()
{
    SalesLine_DS.OnQueryExecuting += eventhandler(this.parmFilterFormQueryEventHandler().applyFilter);
}

/// <summary>
///    AVA <c>docCursor</c> method.
/// </summary>
/// <returns>
///    <c>Common</c> as return value
/// </returns>
public Common docCursor()
{
    Common docCursor;

    docCursor = super();

    if (docCursor.TableId == tableNum(InventDim))
    {
        docCursor = salesLine;
    }

    return docCursor;
}

/// <summary>
///    AVA <c>initFrmValues</c> method.
/// </summary>
void initFrmValues()
{
    Common          locCommon;

    frmLanguageId           = CompanyInfo::find().LanguageId;
    frmUserId               = curUserId();
    frmHcmWorkerRecId       = HcmWorkerLookup::currentWorker();
    frmHCMWorker            = HCMWorker::find(frmHcmWorkerRecId);
    frmAVAWorkerInventSite  = AVAWorkerInventSite::find(frmHCMWorker.PersonnelNumber);

    frmInitialInventSiteId  = frmAVAWorkerInventSite.InventSiteId;

    frmAVAItemSetParameters = AVAItemSetParameters::find();

    if (element.args().caller() is SysIFilterProvider)
    {
        element.args().lookupRecord(null);
        element.args().record(null);
    }

    if(element.args())
    {
        frmArgs = new Args();
        frmArgs = element.args();
    }

    if(     element.args()
        &&  element.args().menuItemName() == menuitemDisplayStr(AVASalesLineBackOrderReleaseShipment)   )
    {
        if(frmArgs.record())
        {
            locCommon = frmArgs.record();

            switch(locCommon.TableId)
            {
                case Tablenum(SalesTable):
                    frmSalesTable   = locCommon;
                    frmSalesId      = frmSalesTable.SalesId;
                    break;

                case Tablenum(SalesLine):
                    frmSalesLine    = locCommon;
                    frmSalesId      = frmSalesLine.SalesId;
                    frmSalesTable   = SalesTable::find(frmSalesId);
                    break;
            }
            frmReleaseForShipmentMode = true;

            //element.design().viewEditMode(ViewEditMode::Edit);
        }
    }

    frmKCS_TonnageSetup = KCS_TonnageSetup::find();
}

/// <summary>
///    AVA <c>init</c> method.
/// </summary>
void init()
{
    date            initialDateValue;
    FormRealControl locFormRealControl;

    this.initFrmValues();

    super();

    salesLine_ds.query().dataSourceTable(tablenum(SalesLine)).clearRange(fieldnum(SalesLine, ShippingDateRequested));

    backorderDateSalesLine = salesLine_ds.query().dataSourceTable(tablenum(SalesLine)).addRange(fieldnum(SalesLine, ConfirmedDlv));

    element.mcrSetRangeValue();

    initialDateValue = DateTimeUtil::getSystemDate(DateTimeUtil::getUserPreferredTimeZone()) - 1;

    if (    element.args() 
        &&  element.args().menuItemName() != menuitemDisplayStr(AVASalesDelayedOrders)   )
    {
        int backOrderDays = real2int(MCROrderParameters::find().BackorderDays);
        if (backOrderDays > 1)
        {
            initialDateValue -= (backorderDays -1);
        }
    }

    if(frmReleaseForShipmentMode)
    {
        element.design().caption("@NDX:NXAReleaseForShipment");

        TransferToSalesLine.enabled(true);

        GridFilterGroupStandard.enabled(false);
        GridFilterGroupStandard.visible(false);

        ReleaseForShipmentGroup.visible(true);
        AVASalesLineBackOrderReleaseShipment.visible(false);

        SalesLine_KCS_SOCPickingReleaseIndicator.visible(false);
        SalesLineTmpFields.visible(true);
        /**///SalesLine_KCS_SOCPickingReleaseIndicator.visible(true);

        initialDateValue = maxDate();
    }
    else
    {
        GridFilterInventSiteId.enabled(true);

        ReleaseForShipmentGroup.visible(false);
        MenuButtonApprovals.visible(false);
        /* instead display methods used dierect from SalesLine
        AVAShippingQtysTmp.visible(false);
        */
    }

    backorderDate.dateValue(initialDateValue);

    element.updateDesign(InventDimFormDesignUpdate::Init);

    if (#PdsCatchWeightEnabled)
    {
        //SalesLine_PdsCWQty.visible(true);
        CWQtyRow.visible(true);
    }

    GridFilterInventSiteId.text(frmInitialInventSiteId);

    this.initQuery();
    this.replaceSortOrder();
    this.addFilterPaneRanges();
    this.initQueryRanges();

    if(frmReleaseForShipmentMode)
    {
        if(frmSalesLine.RecId && frmSalesLine.SalesType == SalesType::Journal)
        {
            ButtonGroupApproval.enabled(false);
        }
        else if(frmSalesTable.RecId && frmSalesTable.SalesType == SalesType::Journal)
        {
            ButtonGroupApproval.enabled(false);
        }
    }

    if(frmSalesTable.RecId && frmSalesTable.AVAPrintReceiptDate == NoYes::Yes)
    {
        ReleasForShipment_ReceiptDateConfirmed.allowEdit(true);
    }

    //locFormRealControl  = element.design().controlName(formControlStr(AVASalesLineBackOrder, ReleasForShipment_ShipmentWorkload));
    locFormRealControl  = ReleasForShipment_ShipmentWorkload;
    frmColorScheme      = locFormRealControl.colorScheme();
    frmBackgroundColor  = locFormRealControl.backgroundColor();
}

