/// <summary>
///    AVA <c>inventDimSetupObject</c> method.
/// </summary>
/// <returns>
///    <c>InventDimCtrl_Frm_OnhandItem</c> as return value
/// </returns>
InventDimCtrl_Frm_OnhandItem inventDimSetupObject()
{

    if (!inventDimFormSetup)
    {
        inventDimFormSetup  = InventDimCtrl_Frm_OnhandItem::newFromForm(element);
        inventDimFormSetup.parmLargeRightClickForm(NoYes::Yes);
        inventDimFormSetup.parmGroupByNameAlias(NoYes::Yes);
        InventDimParm       inventDimParm =  inventDimFormSetup.parmDimParmVisible();
        inventDimParm = inventDimFormSetup.parmDimParmVisible();

        inventDimParm.InventSiteIdFlag = NoYes::Yes;
        inventDimParm.InventLocationIdFlag = NoYes::Yes;
        inventDimFormSetup.parmDimParmVisible(inventDimParm);
    }
    return inventDimFormSetup;
}

/// <summary>
///    AVA <c>mcrSetRangeValue</c> method.
/// </summary>
public void mcrSetRangeValue()
{
    str         custAccounts;
    CustTable   custTable;
    CustTable   custTableBuffer;

    if (isConfigurationkeyEnabled(configurationKeyNum(MCRCallCenter))
        && element.args().dataset() == tableNum(CustTable))
    {
        // Not only show backorder lines (sales line query) for the current customer but any accounts
        // that were merged into the current customer.
        custTable = element.args().record();

        custAccounts = SysQuery::value(custTable.AccountNum);

        while select AccountNum from custTableBuffer
            where custTableBuffer.MCRMergedRoot == custTable.AccountNum
        {
            custAccounts += strfmt(',%1',SysQuery::value(custTableBuffer.AccountNum));
        }

        salesLine_ds.queryBuildDataSource().addRange(fieldNum(SalesLine, CustAccount)).value(custAccounts);
    }
}

/// <summary>
///    AVA <c>updateDesign</c> method.
/// </summary>
/// <param name="mode">
///    <c>InventDimFormDesignUpdate</c> as type
/// </param>
void updateDesign(InventDimFormDesignUpdate mode)
{
    switch (mode)
    {
        case InventDimFormDesignUpdate::Init          :
            // No break
        case InventDimFormDesignUpdate::LinkActive    :
            element.inventDimSetupObject().initFromCaller();
            element.inventDimSetupObject().parmCtrlItemId(GroupInventSum_Item_ItemId);

            if (mode == InventDimFormDesignUpdate::Init)
            {
                if (element.inventDimSetupObject().parmDimParmVisibleGrid().ItemIdFlag == NoYes::No)
                {
                    GroupInventSum_ItemName.visible(false);
                }
            }
            element.inventDimSetupObject().parmDimParmVisible(element.inventDimSetupObject().parmDimParmVisibleGrid());
            // No break
        case InventDimFormDesignUpdate::Active        :
            element.inventDimSetupObject().formActiveSetup();
            element.inventDimSetupObject().formSetControls(true,true);
            break;

        default :
            throw error(strFmt("@SYS54195",funcName()));
    }
}

/// <summary>
///     AVA <c>addFilterPaneRanges</c> method.
/// </summary>
public void addFilterPaneRanges()
{
    QueryBuildDataSource salesTableQBDS;

    salesTableQBDS = SalesTable_DS.query().dataSourceName(SalesTable_DS.name());

    SysQuery::findOrCreateRange(salesTableQBDS, fieldNum(SalesTable, InventSiteId));
}

/// <summary>
///     AVA <c>replaceSortOrder</c> method.
/// </summary>
public void replaceSortOrder()
{
    QueryBuildDataSource salesLineQBDS;

    salesLineQBDS = SalesLine_DS.query().dataSourceName(SalesLine_DS.name());
    salesLineQBDS.clearSortIndex();
    salesLineQBDS.addSortField(fieldNum(SalesLine, SalesId), SortOrder::Ascending);
    salesLineQBDS.addSortField(fieldNum(SalesLine, LineNum), SortOrder::Ascending);
}

/// <summary>
///     AVA <c>initQueryRanges</c> method.
/// </summary>
public void initQueryRanges()
{
    QueryBuildDataSource    salesLineQBDS;
    QueryBuildDataSource    inventSumQBDS;
    QueryBuildRange         salesTypeRange;

    salesLineQBDS = SalesLine_DS.query().dataSourceName(SalesLine_DS.name());
    SysQuery::findOrCreateRange(salesLineQBDS, fieldNum(SalesLine, SalesStatus)).value(queryValue(SalesStatus::Backorder));
    SysQuery::findOrCreateRange(salesLineQBDS, fieldNum(SalesLine, RemainSalesPhysical)).value(SysQuery::valueNot(0));

    if(frmSalesLine.RecId)
    {
        SysQuery::findOrCreateRange(salesLineQBDS, fieldNum(SalesLine, InventTransId)).value(frmSalesLine.InventTransId);
    }
    else if(frmSalesTable.RecId)
    {
        SysQuery::findOrCreateRange(salesLineQBDS, fieldNum(SalesLine, SalesId)).value(frmSalesTable.SalesId);
    }

    inventSumQBDS = InventSum_DS.query().dataSourceName(inventSum_DS.name());
    SysQuery::findOrCreateRange(inventSumQBDS, fieldNum(InventSum, InventSiteId)).value(queryValue(frmAVAWorkerInventSite));

    salesTypeRange = SysQuery::findOrCreateRange(SalesTable_ds.query().dataSourceTable(tableNum(SalesTable)), fieldNum(SalesTable,SalesType));
    if (salesTypeRange)
    {
        if (frmSalesId == '')
        {
            salesTypeRange.value(SysQuery::valueNot(SalesType::Journal));
        }
        else
        {
            salesTypeRange.value(SysQuery::valueUnlimited());
        }
    }

    SysQuery::findOrCreateRange(salesLineQBDS, fieldNum(SalesLine, AVAItemSet)).value(SysQuery::valueNot(NoYes::Yes));
}

/// <summary>
///     AVA <c>initQuery</c> method.
/// </summary>
public void initQuery()
{
    QueryBuildDataSource salesTableQBDS;

    salesTableQBDS = SalesTable_DS.query().dataSourceName(SalesTable_DS.name());
    if (    !element.args()
        ||  element.args().menuItemName() != menuitemDisplayStr(AVASalesDelayedOrders)  )
    {
        SalesTable_DS.query().dataSourceTable(tableNum(HcmWorker)).enabled(false);
    }
}

