/// <summary>
///    AVA <c>deleteAVASalesLineTmpTable</c> method.
/// </summary>
private void deleteAVASalesLineTmpTable()
{
    frmAVASalesLineBackOrderTmp = AVASalesLineBackOrderTmp_DS.getFirst() as AVASalesLineBackOrderTmp;

    delete_from frmAVASalesLineBackOrderTmp;
}

/// <summary>
///    AVA <c>createSalesLineTmpTableRecord</c> method.
/// </summary>
/// <param name="mode">
///    <c>SalesLine</c> as type
/// </param>
/// <returns>
///    <c>AVASalesLineBackOrderTmp</c> as return value
/// </returns>
private AVASalesLineBackOrderTmp createSalesLineTmpTableRecord(SalesLine _salesLine, AVASalesLineBackOrderTmp _avaSalesLineBackOrderTmp)
{
    SalesLine                   locSalesLine;
    AVASalesLineBackOrderTmp    locAVASalesLineBackOrderTmp;

    locSalesLine                = _salesLine;
    locAVASalesLineBackOrderTmp = _avaSalesLineBackOrderTmp;

    locAVASalesLineBackOrderTmp.clear();
    locAVASalesLineBackOrderTmp.SalesLineRefRecId               = locSalesLine.RecId;
    locAVASalesLineBackOrderTmp.SalesId                         = locSalesLine.SalesId;
    locAVASalesLineBackOrderTmp.InventTransId                   = locSalesLine.InventTransId;
    locAVASalesLineBackOrderTmp.ItemId                          = locSalesLine.ItemId;
    locAVASalesLineBackOrderTmp.InventDimId                     = locSalesLine.InventDimId;
    locAVASalesLineBackOrderTmp.SalesType                       = locSalesLine.SalesType;
    locAVASalesLineBackOrderTmp.SalesStatus                     = locSalesLine.SalesStatus;
    locAVASalesLineBackOrderTmp.SalesQty                        = locSalesLine.SalesQty;
    locAVASalesLineBackOrderTmp.SalesQtyPossible                = 0;
    locAVASalesLineBackOrderTmp.SalesQtyEffective               = 0;

    locAVASalesLineBackOrderTmp.AVAStockAvailability            = locSalesLine.avaGetStockAvailablity();
    locAVASalesLineBackOrderTmp.KCS_SOCPickingReleaseIndicator  = locSalesLine.KCS_SOCPickingReleaseIndicator;
    locAVASalesLineBackOrderTmp.Processed                       = NoYes::No;
    /* instead display methods used dierect from SalesLine
    locAVASalesLineBackOrderTmp.AVAPhysicalAvailAbilityForShipping      = locSalesLine.avaPhysicalAvailAbilityForShipping();
    locAVASalesLineBackOrderTmp.AVAPhysicalReservedAbilityForShipping   = locSalesLine.avaPhysicalReservedAbilityForShipping();
    locAVASalesLineBackOrderTmp.AVAPhysicalAvailForShipping             = locAVASalesLineBackOrderTmp.AVAPhysicalAvailAbilityForShipping - locAVASalesLineBackOrderTmp.AVAPhysicalReservedAbilityForShipping;
    */

    locAVASalesLineBackOrderTmp.insert();

    return locAVASalesLineBackOrderTmp;
}

/// <summary>
///    AVA <c>createSalesLineTmpTableData</c> method.
/// </summary>
/// <returns>
///    <c>AVASalesLineBackOrderTmp</c> as return value
/// </returns>
private AVASalesLineBackOrderTmp createSalesLineTmpTableData()
{
    SalesLine                   locSalesLine;
    AVASalesLineBackOrderTmp    locAVASalesLineBackOrderTmp;
    TransDate                   locTransDate;

    this.deleteAVASalesLineTmpTable();

    ReleasForShipment_DateNextAvailableMax.dateValue(dateNull());

    if(frmSalesTable.RecId)
    {
        while select locSalesLine
        where   locSalesLine.SalesId    == frmSalesTable.SalesId
        {
            if(locSalesLine.AVAItemSet != NoYes::Yes)
            {
                locAVASalesLineBackOrderTmp = this.createSalesLineTmpTableRecord(locSalesLine, locAVASalesLineBackOrderTmp);
            }

            locTransDate = locSalesLine.avaDateNextAvailable();
            if(ReleasForShipment_DateNextAvailableMax.dateValue() < locTransDate)
            {
                ReleasForShipment_DateNextAvailableMax.dateValue(locTransDate);
            }
        }
    }
    else
    {
        locSalesLine  = salesLine_ds.getFirst(true) as SalesLine;
        if (locSalesLine)
        {
            while (locSalesLine)
            {
                if(locSalesLine.AVAItemSet != NoYes::Yes)
                {
                    locAVASalesLineBackOrderTmp = this.createSalesLineTmpTableRecord(locSalesLine, locAVASalesLineBackOrderTmp);
                }

                locTransDate = locSalesLine.avaDateNextAvailable();
                if(ReleasForShipment_DateNextAvailableMax.dateValue() < locTransDate)
                {
                    ReleasForShipment_DateNextAvailableMax.dateValue(locTransDate);

                }
                locSalesLine = salesLine_ds.getNext() as SalesLine;
            }
        }
    }
    return locAVASalesLineBackOrderTmp;
}

/// <summary>
