/// <summary>
///    AVA <c>releaseActualPosition</c> method.
/// </summary>
/// <param name="_avaSalesLineBackOrderTmp">
///    <c>AVASalesLineBackOrderTmp</c> as type
/// </param>
private void releaseSalesLinePosition(AVASalesLineBackOrderTmp _avaSalesLineBackOrderTmp = null)
{
    SalesLine                   locSalesLine;
    AVASalesLineBackOrderTmp    locAVASalesLineBackOrderTmp;

    AVAStockAvailability        locAVAStockAvailability;

    boolean                     locCheckFailed;

    if(_avaSalesLineBackOrderTmp)
    {
        locAVASalesLineBackOrderTmp = _avaSalesLineBackOrderTmp;
    }
    else
    {
        locAVASalesLineBackOrderTmp = AVASalesLineBackOrderTmp;
    }
    locSalesLine = SalesLine::findRecId(locAVASalesLineBackOrderTmp.SalesLineRefRecId);

    locAVAStockAvailability = locSalesLine.avaGetStockAvailablity();

    if(locAVAStockAvailability == AVAStockAvailability::NotAvailable)
    {
        locCheckFailed = checkFailed("@NDX:NXAReleasePositionNotPossible");
    }
    else if(    locAVAStockAvailability == AVAStockAvailability::PartitialAvailable 
            &&  !locAVASalesLineBackOrderTmp.KCS_SOCPickingReleaseIndicator         )
    {
        locCheckFailed = checkFailed("@NDX:NXASwitchReleaseForShipmentHaveToBeSet");
    }
    else if(    locAVAStockAvailability == AVAStockAvailability::Available 
            ||  locAVAStockAvailability == AVAStockAvailability::IndividualRequired)
    {
        ttsBegin;
        if(!locAVASalesLineBackOrderTmp.KCS_SOCPickingReleaseIndicator)
        {
            locAVASalesLineBackOrderTmp.selectForUpdate(true);
            locAVASalesLineBackOrderTmp.KCS_SOCPickingReleaseIndicator  = NoYes::Yes;
            locAVASalesLineBackOrderTmp.update();

            //element.processTmpTablePositions(locAVASalesLineBackOrderTmp);  // deactivated for Indicator change only
        }
        element.processTmpTablePositions(locAVASalesLineBackOrderTmp);      // added for date change even position release indiccator was not changed
        //element.releaseSingleSalesLinePosition(locSalesLine);               // managed over tmpTable process, not needed anymore
        ttsCommit;
    }
}

/// <summary>
///    AVA <c>releaseSingleSalesLinePosition</c> method.
/// </summary>
/// <param name="_salesLine">
///    <c>SalesLine</c> as type
/// </param>
private void releaseSingleSalesLinePosition(SalesLine _salesLine)
{
    SalesLine   locSalesLine;

    ttsBegin;
    locSalesLine                                = _salesLine;
    locSalesLine.selectForUpdate(true);
    locSalesLine.KCS_SOCPickingReleaseIndicator = NoYes::Yes;
    locSalesLine.update();

    locSalesLine.avaItemSetSalesLineSetKCS_SOCPickingReleaseIndicator(true); // with siblings

    locSalesLine.avaUpdateSalesTableKCS_PickingReleaseIndicator();
    ttsCommit;

    SalesLine_DS.reread();
    SalesLine_DS.refresh();
}

/// <summary>
///    AVA <c>processTmpTablePositions</c> method.
/// </summary>
/// <param name="_singleAVASalesLineBackOrderTmp">
///    <c>AVASalesLineBackOrderTmp</c> as type
/// </param>
private void processTmpTablePositions(AVASalesLineBackOrderTmp  _singleAVASalesLineBackOrderTmp = null)
{
    SalesLine                   locSalesLine;
    AVAStockAvailability        locAVAStockAvailability;
    RefRecId                    locSingleAVASalesLineBackOrderTmpRecId;
    boolean                     tmpTableModified;
    boolean                     salesLineModified;

    boolean                     locApprovalMarkAvailablePossible;
    boolean                     locReleaseFunctionReleaseMarkedPossible;
    boolean                     locApprovalMarkAvailableFound;

    boolean                     allTmpTablePositionsAvailableIndividual;
    boolean                     locReleaseFunctionsReservations;

    SalesReceiptDateConfirmed   locReceiptDateConfirmed;

    boolean                     locApprovalSaveOpenChanges;

    boolean                     locReleaseFunctionReleaseMarked;
    boolean                     locReleaseFunctionsShippingDateTmp;
    boolean                     locReleaseFunctionsReservationsTmp;

    boolean                     locReleaseFunctionReleaseMarkedSaveOpenChanges;

    InventQty                   locRemainInventQtyToReserve;

    DialogButton                locDialogButton;

    boolean                     locGetSalesLinesFromDB;

    boolean                     locCheckFailed;
    boolean                     locShippingDateConfirmedInHeaderMissing;
    boolean                     locShippingDateConfirmedInPositionsMissing;

    boolean                     locReleaseIndicatorBothNo;
    boolean                     locReleaseIndicatorBothYes;
    boolean                     locReleaseIndicatorChanged;
    boolean                     locReleaseIndicatorChangedFromNoToYes;
    boolean                     locReleaseIndicatorChangedFromYesToNo;


    void checkPickingReleaseIndicatorChanged()
    {
        locReleaseIndicatorBothNo               = false;
        locReleaseIndicatorBothYes              = false;
        locReleaseIndicatorChanged              = false;
        locReleaseIndicatorChangedFromNoToYes   = false;
        locReleaseIndicatorChangedFromYesToNo   = false;

        if(locSalesLine.KCS_SOCPickingReleaseIndicator != AVASalesLineBackOrderTmp.KCS_SOCPickingReleaseIndicator)
        {
            locReleaseIndicatorChanged                  = true;

            if(AVASalesLineBackOrderTmp.KCS_SOCPickingReleaseIndicator == NoYes::Yes)
            {
                locReleaseIndicatorChangedFromNoToYes   = true;
            }
            else
            {
                locReleaseIndicatorChangedFromYesToNo   = true;
            }
        }
        else    // equal values
        {
            if(AVASalesLineBackOrderTmp.KCS_SOCPickingReleaseIndicator == NoYes::Yes)
            {
                locReleaseIndicatorBothYes              = true;
            }
            else
            {
                locReleaseIndicatorBothNo               = true;
            }
        }
    }


    void processReservation()
    {
        if( locSalesLine.RemainInventPhysical > 0.0)
        {
            locRemainInventQtyToReserve = locSalesLine.avaRemainInventQtyNotReserved();
            if(locRemainInventQtyToReserve)
            {
                if(salesLineModified)
                {
                    locSalesLine.selectForUpdate(true);
                    locSalesLine.update();

                    locSalesLine.avaItemSetSalesLineSetKCS_SOCPickingReleaseIndicator();

                    locSalesLine.avaUpdateSalesTableKCS_PickingReleaseIndicator();
                    salesLineModified = false;
                }
                locSalesLine.avaReserveSalesLine(locSalesLine, locRemainInventQtyToReserve);
                locSalesLine.reread();
                salesLineModified = false;
            }
        }
    }


    locSingleAVASalesLineBackOrderTmpRecId = _singleAVASalesLineBackOrderTmp.RecId;

    allTmpTablePositionsAvailableIndividual = true;

    if(frmReleasePosition)                      // "Positionsfreigabe"
    {
        frmReleaseFunctionReleaseMarked = true; // "Teilfreigabe"
    }

    if(frmReleaseFunctionReleaseAll)            // "Komplettfreigabe"
    {
        frmApprovalMarkAvailable        = true; // "Verfügbare markieren" - Grün markieren
        frmReleaseFunctionReleaseMarked = true; // "Teilfreigabe"
    }

    if(frmReleaseFunctionReleaseMarked)         // "Teilfreigabe"
    {
        frmReleaseFunctionsShippingDate = true; // "Freigabefunktionen - Versanddatum"
        frmReleaseFunctionsReservations = true; // "Freigabefunktionen - Reservierungen"
        if(     frmReleasePosition
            &&  _singleAVASalesLineBackOrderTmp.Processed   )
        {
            frmReleaseFunctionsReservations = false; // "Freigabefunktionen - Reservierungen bereits fertig"
        }
    }


    // pre check tmp table for changes
    this.setShippingDateConfirmedFormValues();

    locShippingDateConfirmedInHeaderMissing     = !this.checkReleasForShipment_ShippingDateConfirmed();
    locShippingDateConfirmedInPositionsMissing  = false;

    while select AVASalesLineBackOrderTmp
    {
        locSalesLine = SalesLine::findInventTransId(AVASalesLineBackOrderTmp.InventTransId);

        checkPickingReleaseIndicatorChanged();

        locApprovalMarkAvailablePossible    = false;

        if(frmApprovalMarkAvailable)                                                                // "Verfügbare markieren" - Grün markieren
        {
            locAVAStockAvailability = locSalesLine.avaGetStockAvailablity();

            if(     (locAVAStockAvailability    == AVAStockAvailability::Available)
                ||  (locAVAStockAvailability    == AVAStockAvailability::IndividualRequired)    )
            {
                if(locReleaseIndicatorBothNo)
                {
                    locApprovalMarkAvailablePossible    = true;                                     // current position possible to be marked
                }
            }

            if(     locApprovalMarkAvailablePossible
                &&  locSalesLine.AVAItemSetComponent)
            {
                locApprovalMarkAvailablePossible = this.checkItemSetComponentReleasable(locSalesLine);
            }

            if(locApprovalMarkAvailablePossible) // possible to be marked but check ShippingDateConfirmed
            {
                if(     locSalesLine.ShippingDateConfirmed == dateNull()
                    &&  locShippingDateConfirmedInHeaderMissing         )
                {
                    locApprovalMarkAvailablePossible            = false;
                    locShippingDateConfirmedInPositionsMissing  = true;
                }
            }
        }

        if(frmReleaseFunctionReleaseMarked)                                                         // "Teilfreigabe"
        {
            if(     frmReleasePosition                              == false
                ||  (       frmReleasePosition                      == true                         // "Positionsfreigabe"
                        &&  locSingleAVASalesLineBackOrderTmpRecId
                        &&  locSingleAVASalesLineBackOrderTmpRecId  == AVASalesLineBackOrderTmp.RecId)    )
            {
                if(     locApprovalMarkAvailablePossible                                            // current position possible to be marked, but not marked
                    &&  locReleaseIndicatorBothNo       )
                {
                    locReleaseFunctionReleaseMarkedPossible = true;
                }                                                                                   
                if(locReleaseIndicatorChangedFromNoToYes)                                           // current position marked for release
                {
                    locReleaseFunctionReleaseMarkedPossible = true;
                }
                if(locReleaseFunctionReleaseMarkedPossible) // possible to be released but check ShippingDateConfirmed
                {
                    if(     locSalesLine.ShippingDateConfirmed == dateNull()
                        &&  locShippingDateConfirmedInHeaderMissing         )
                    {
                        locReleaseFunctionReleaseMarkedPossible     = false;
                        locShippingDateConfirmedInPositionsMissing  = true;
                    }
                }
            }
            if(locReleaseIndicatorChangedFromNoToYes)                                               // current position marked for release
            {
                // check shippingdateconfirmed
                if(frmSalesShippingDateConfirmed == dateNull())
                {
                    if(locSalesLine.avaItemSetConfirmedDatesSet(true, true, false) == false)
                    {
                        //warning("@NDX:NXAPositionShippingDateConfirmedMissing");
                        this.checkFailedShippingDateConfirmed();
                        return;
                    }
                }
            }
        }

        if(frmReleaseFunctionReleaseAll)                                                            // "Komplettfreigabe"
        {
            if(     !(AVASalesLineBackOrderTmp.AVAStockAvailability == AVAStockAvailability::Available)
                &&  !(AVASalesLineBackOrderTmp.AVAStockAvailability == AVAStockAvailability::IndividualRequired))
            {
                allTmpTablePositionsAvailableIndividual = false;                                    // existing position(s) not releasable
            }
        }

        if(frmReleaseFunctionsReservations)                                                         // "Freigabefunktionen - Reservierungen"
        {
            if(     frmReleasePosition                              == false     
                ||  (       frmReleasePosition                      == true                         // "Positionsfreigabe"
                        &&  locSingleAVASalesLineBackOrderTmpRecId
                        &&  locSingleAVASalesLineBackOrderTmpRecId  == AVASalesLineBackOrderTmp.RecId)    )
            {
                if(     (AVASalesLineBackOrderTmp.AVAStockAvailability == AVAStockAvailability::Available)
                    ||  (AVASalesLineBackOrderTmp.AVAStockAvailability == AVAStockAvailability::IndividualRequired) )
                {
                    if(     locReleaseIndicatorChangedFromNoToYes
                        &&  locSalesLine.RemainInventPhysical                       > 0.0)
                    {
                        locReleaseFunctionsReservations         = true;

                        if(!locRemainInventQtyToReserve)                                             // first hit for not reserved qtys
                        {
                            locRemainInventQtyToReserve = locSalesLine.avaRemainInventQtyNotReserved();
                        }
                    }
                }
            }
        }

        if(frmApprovalSaveOpenChanges)                                                              // "Änderungen speichern"
        {
            if(locSalesLine.KCS_SOCPickingReleaseIndicator != AVASalesLineBackOrderTmp.KCS_SOCPickingReleaseIndicator)  
            {
                locApprovalSaveOpenChanges  = true;                                                 // KCS_SOCPickingReleaseIndicator has changed in at least one position

                if(AVASalesLineBackOrderTmp.KCS_SOCPickingReleaseIndicator)                                             
                {
                    locReleaseFunctionReleaseMarkedSaveOpenChanges  = true;                         // KCS_SOCPickingReleaseIndicator activated in at least one position

                    if(!locRemainInventQtyToReserve)
                    {
                        locRemainInventQtyToReserve = locSalesLine.avaRemainInventQtyNotReserved();
                    }
                }
            }
        }
    }

    if(     locShippingDateConfirmedInPositionsMissing 
        &&  locShippingDateConfirmedInHeaderMissing     )
    {
        locCheckFailed = this.checkFailedShippingDateConfirmed();
        return;
    }


    // react on results of check
    if(frmReleaseFunctionReleaseAll && !allTmpTablePositionsAvailableIndividual)                    // "Komplettfreigabe"
    {
        info("@NDX:NXANotAllPositionsDeliverableMarkSingleOnes");
    }

    if(     frmReleaseForShipmentSaveWhenClosing 
        &&  locApprovalSaveOpenChanges 
        &&  !frmCloseESCOk                      )
    {
        locDialogButton = Box::yesNo(   "@SYS21594",
                                        DialogButton::Yes,
                                        "@NDX:NXAReleaseForShipment"
                                        );
        if (locDialogButton != DialogButton::Yes)
        {
            locApprovalSaveOpenChanges = false; // "Änderungen speichern"
        }
    }


    if(     (frmReleaseFunctionsReservations    && locReleaseFunctionsReservations  )               // "Freigabefunktionen - Reservierungen"
        ||  (frmApprovalSaveOpenChanges         && locApprovalSaveOpenChanges       )   )           // "Änderungen speichern"
    {
        if(locRemainInventQtyToReserve)  // reservable qtys found
        {
            if(!frmReleaseFunctionReleaseMarked)                                                     // "Teilfreigabe" and with this "Positionsfreigabe", "Komplettfreigabe"
            {
                locDialogButton = Box::yesNo(   "@NDX:NXAReservePositionsForThisSalesOrder",
                                                DialogButton::Yes,
                                                "@SYS7669"
                                                );
                if (locDialogButton == DialogButton::Yes)
                {
                    locReleaseFunctionsReservations = true;
                }
                else
                {
                    locReleaseFunctionsReservations = false;
                }
            }
        }
        else
        {
            locReleaseFunctionsReservations = false;
        }
    }

    if(locApprovalSaveOpenChanges && locReleaseFunctionReleaseMarkedSaveOpenChanges)                // "Änderungen speichern"
    {
        locDialogButton = Box::yesNo(   "@NDX:NXAPositionsMarkedGrantPartialRelease",
                                        DialogButton::Yes,
                                        "@NDX:NXAPartialRelease"
                                        );
        if (locDialogButton == DialogButton::Yes)
        {
            locReleaseFunctionReleaseMarkedSaveOpenChanges = true;
        }
        else
        {
            locReleaseFunctionReleaseMarkedSaveOpenChanges = false;
        }
    }

    // Process changes on tmpTable and salesLine
    ttsbegin;
    while select forupdate AVASalesLineBackOrderTmp
    {
        locSalesLine            = SalesLine::findInventTransId(AVASalesLineBackOrderTmp.InventTransId);

        checkPickingReleaseIndicatorChanged();

        if(frmApprovalMarkAvailable)                                                                // "Verfügbare markieren" - Grün markieren
        {
            locAVAStockAvailability = locSalesLine.avaGetStockAvailablity();

            if(     (locAVAStockAvailability    == AVAStockAvailability::Available)
                ||  (locAVAStockAvailability    == AVAStockAvailability::IndividualRequired)    )
            {
                if(locReleaseIndicatorBothNo)
                {
                    locApprovalMarkAvailableFound                           = true;

                    if(     locApprovalMarkAvailableFound 
                        &&  locSalesLine.AVAItemSetComponent    )
                    {
                        locApprovalMarkAvailableFound = this.checkItemSetComponentReleasable(locSalesLine);
                    }

                    if(locApprovalMarkAvailableFound)
                    {
                        AVASalesLineBackOrderTmp.KCS_SOCPickingReleaseIndicator = NoYes::Yes;
                        tmpTableModified                                        = true;
                    }
                }
            }
        }

        if(frmReleaseFunctionReleaseMarked)                                                         // Teilfreigabe
        {
            if(     locSalesLine.KCS_SOCPickingReleaseIndicator             == NoYes::No 
                &&  AVASalesLineBackOrderTmp.KCS_SOCPickingReleaseIndicator == NoYes::Yes   )
            {
                if(     frmReleasePosition                              == false
                    ||  (       frmReleasePosition                      == true                     // "Positionsfreigabe"
                            &&  locSingleAVASalesLineBackOrderTmpRecId
                            &&  locSingleAVASalesLineBackOrderTmpRecId  == AVASalesLineBackOrderTmp.RecId)    )
                {
                    //processReservation();
                    locSalesLine.KCS_SOCPickingReleaseIndicator = NoYes::Yes;
                    salesLineModified                           = true;
                }

                locReleaseFunctionReleaseMarked                 = true;
            }
            else
            {
                locReleaseFunctionReleaseMarked                 = false;
            }
        }

        if(frmApprovalSaveOpenChanges && locApprovalSaveOpenChanges)                                // "Änderungen speichern"
        {
            if(locReleaseIndicatorChanged)
            {
                locSalesLine.KCS_SOCPickingReleaseIndicator = AVASalesLineBackOrderTmp.KCS_SOCPickingReleaseIndicator;
                salesLineModified                           = true;

                locReleaseFunctionsShippingDateTmp          = frmReleaseFunctionsShippingDate;      // "Freigabefunktionen - Versanddatum"
                locReleaseFunctionsReservationsTmp          = frmReleaseFunctionsReservations;      // "Freigabefunktionen - Reservierungen"
                frmReleaseFunctionsShippingDate             = true;                                 // "Freigabefunktionen - Versanddatum"
                frmReleaseFunctionsReservations             = true;                                 // "Freigabefunktionen - Reservierungen"
            }
        }

        if(frmReleaseFunctionsShippingDate && frmReleaseFunctionReleaseMarked)                      // "Freigabefunktionen - Versanddatum"
        {
            if(     frmReleasePosition                              == false
                ||  (       frmReleasePosition                      == true                         // "Positionsfreigabe"
                        &&  locSingleAVASalesLineBackOrderTmpRecId
                        &&  locSingleAVASalesLineBackOrderTmpRecId  == AVASalesLineBackOrderTmp.RecId)    )
            {
                if(frmSalesShippingDateConfirmed != dateNull())
                {
                    if(     frmSalesShippingDateConfirmed != locSalesLine.ShippingDateConfirmed 
                        &&  AVASalesLineBackOrderTmp.KCS_SOCPickingReleaseIndicator             )
                    {
                        if(locSalesLine.ShippingDateConfirmed == dateNull())
                        {
                            locSalesLine.ShippingDateConfirmed  = frmSalesShippingDateConfirmed;
                            locSalesLine.avaItemSetAdjustShippingDates(true);
                            salesLineModified                   = true;
                        }
                        else
                        {
                            if(frmShippingDateOverwrite)
                            {
                                locSalesLine.ShippingDateConfirmed  = frmSalesShippingDateConfirmed;
                                locSalesLine.avaItemSetAdjustShippingDates(true);
                                salesLineModified                   = true;
                            }
                        }
                    }
                }
                locReceiptDateConfirmed = ReleasForShipment_ReceiptDateConfirmed.dateValue();
                if(locReceiptDateConfirmed != dateNull())
                {
                    if(locReceiptDateConfirmed != locSalesLine.ReceiptDateConfirmed && AVASalesLineBackOrderTmp.KCS_SOCPickingReleaseIndicator)
                    {
                        if(locSalesLine.ReceiptDateConfirmed == dateNull())
                        {
                            locSalesLine.ReceiptDateConfirmed   = locReceiptDateConfirmed;
                            locSalesLine.avaItemSetAdjustReceiptDates(true);
                            salesLineModified                   = true;
                        }
                        else
                        {
                            if(frmShippingDateOverwrite)
                            {
                                locSalesLine.ReceiptDateConfirmed   = locReceiptDateConfirmed;
                                locSalesLine.avaItemSetAdjustReceiptDates(true);
                                salesLineModified                   = true;
                            }
                        }
                    }
                }
            }
        }

        if(frmReleaseFunctionsReservations && locReleaseFunctionReleaseMarked)                      // "Freigabefunktionen - Reservierungen"
        {
            if(     frmReleasePosition                              == false
                ||  (       frmReleasePosition                      == true                         // "Positionsfreigabe"
                        &&  locSingleAVASalesLineBackOrderTmpRecId
                        &&  locSingleAVASalesLineBackOrderTmpRecId  == AVASalesLineBackOrderTmp.RecId)    )
            {
                if(!frmBlockReservations)
                {
                    processReservation();

                    locGetSalesLinesFromDB = true;
                }
            }
        }

        if(frmApprovalSaveOpenChanges && locApprovalSaveOpenChanges)                                // "Änderungen speichern"
        {
            frmReleaseFunctionsShippingDate                 = locReleaseFunctionsShippingDateTmp;   // "Freigabefunktionen - Versanddatum"
            frmReleaseFunctionsReservations                 = locReleaseFunctionsReservationsTmp;   // "Freigabefunktionen - Reservierungen"

            if(     locReleaseFunctionReleaseMarkedSaveOpenChanges
                &&  AVASalesLineBackOrderTmp.KCS_SOCPickingReleaseIndicator == NoYes::Yes
                &&  locReleaseIndicatorChangedFromNoToYes                                   )
            {
                if(!frmBlockReservations)
                {
                    processReservation();

                    locSalesLine.KCS_SOCPickingReleaseIndicator = NoYes::Yes;
                    salesLineModified                           = true;
                }
            }
            if(locReleaseIndicatorChangedFromYesToNo)
            {
                if(!frmBlockReservations)
                {
                    locSalesLine.ShippingDateConfirmed  = dateNull();
                    locSalesLine.avaItemSetAdjustShippingDates(true);
                    salesLineModified                   = true;
                }
            }
        }

        if(tmpTableModified)
        {
            AVASalesLineBackOrderTmp.selectForUpdate(true);
            AVASalesLineBackOrderTmp.update();
            tmpTableModified = false;
        }

        if(salesLineModified)
        {
            locSalesLine.selectForUpdate(true);
            locSalesLine.update();
            salesLineModified = false;
            locGetSalesLinesFromDB = true;
        }

        locSalesLine.avaItemSetSalesLineSetKCS_SOCPickingReleaseIndicator();

        locSalesLine.avaUpdateSalesTableKCS_PickingReleaseIndicator();
    }
    ttscommit;

    AVASalesLineBackOrderTmp_DS.refresh();
    SalesLine_DS.ReSearch(true);

    if(locGetSalesLinesFromDB == true)
    {
        element.refreshCallerForm();
    }
}

/// <summary>
///    AVA <c>processSelectedPositions</c> method.
/// </summary>
/// <returns>
///    <c>boolean</c> as return value
/// </returns>
private boolean processSelectedPositions()
{
    boolean                 retVal;
    boolean                 releaseCheckedWHSWork;
    boolean                 releaseCheckedReservation;
    boolean                 releaseDoPossibleRevocations;
    boolean                 releaseRevokeReservations;

    DialogButton            locDialogButton;

    int                     found;
    int                     outOf;

    //SalesLine               locRecordsSelected;
    AVASalesLineBackOrderTmp locRecordsSelected;
    SalesLine               locSalesLine;
    SalesLine               locSalesLineItemSet;
    SalesLine               locSalesLineItemSetComponent;
    AVAStockAvailability    locAVAStockAvailability;
    AVASalesLineBackOrderTmp locAVASalesLineBackOrderTmp;

    boolean                 locGetSalesLinesFromDB;

    MultiSelectionHelper    locMSHelper;

    Map                     salesLineMap;
    MapEnumerator           salesLineMapEnumerator;

    InventQty               locInventQty;
    InventQty               locRemainInventQtyToReserve;

    retVal = true;

    locMSHelper     = MultiSelectionHelper::construct();
    salesLineMap    = new Map(Types::Int64, Types::Record);

    //locMSHelper.parmDatasource(SalesLine_DS);
    locMSHelper.parmDatasource(AVASalesLineBackOrderTmp_DS);

    //check selected positions
    locRecordsSelected = locMSHelper.getFirst();
    while (locRecordsSelected.RecId)
    {
        locSalesLine                = SalesLine::findRecId(locRecordsSelected.SalesLineRefRecId);
        locAVASalesLineBackOrderTmp = locRecordsSelected;

        if(     frmApprovalUnmarkUnreserveSelected      // "Aufheben"
            &&  locAVASalesLineBackOrderTmp.RecId   )
        {
            outOf++;
            if(locSalesLine.avaOpenWHSWorkTableExists().RecId)
            {
                found++;
                releaseCheckedWHSWork = true;
            }
            else
            {
                if (!salesLineMap.exists(locSalesLine.RecId))
                {
                    salesLineMap.insert(locSalesLine.RecId, locSalesLine);
                }
                if(!releaseCheckedReservation && locSalesLine.reservedPhysical())
                {
                    releaseCheckedReservation = true;   // reservation found in selected positions
                }
            }
        }

        if(frmApprovalReserveSelected)  // "Reservieren"
        {
            locAVAStockAvailability = locSalesLine.avaGetStockAvailablity();

            if(     locAVAStockAvailability == AVAStockAvailability::Available
                ||  locAVAStockAvailability == AVAStockAvailability::PartitialAvailable )
            {
                locRemainInventQtyToReserve = locSalesLine.avaRemainInventQtyReservable();
                if(locRemainInventQtyToReserve > 0.0)
                {
                    locSalesLine.avaReserveSalesLine(locSalesLine, locRemainInventQtyToReserve); // reserve at least available qty
                    locGetSalesLinesFromDB = true;
                }
            }
        }
        locRecordsSelected = locMSHelper.getNext();
    }

    if(frmApprovalUnmarkUnreserveSelected)  // "Aufheben"
    {
        if(releaseCheckedWHSWork)
        {
            locDialogButton = Box::okCancel(strFmt( "@NDX:NXAP1OfP2NotRevocableDoPossibleRevocation", found, outOf),
                                                    DialogButton::Cancel,
                                                    "@NDX:WIPHelp"
                                                    );
            if (locDialogButton == DialogButton::Ok)
            {
                releaseDoPossibleRevocations = true;
            }
            if(found == outOf)                      // all marked positions have WHSWork, not relevant
            {
                releaseDoPossibleRevocations = false;
            }
        }
        if(releaseCheckedReservation)
        {
            locDialogButton = Box::yesNo(   "@NDX:NXARevokeReservations",
                                            DialogButton::Yes,
                                            "@NDX:NXAReservationsFound"     );
            if (locDialogButton == DialogButton::Yes)
            {
                releaseRevokeReservations = true;
            }
        }
        // process collected positions
        ttsbegin;
        // retrieve from salesLineMap
        salesLineMapEnumerator = salesLineMap.getEnumerator();
        while (salesLineMapEnumerator.moveNext())
        {
            locSalesLine                = salesLineMapEnumerator.currentValue();
            locSalesLine                = SalesLine::findRecId(locSalesLine.RecId, true);
            //locAVASalesLineBackOrderTmp = AVASalesLineBackOrderTmp::findSalesLineRefRecId(locSalesLine.RecId, true);
            locAVASalesLineBackOrderTmp = AVASalesLineBackOrderTmp;
            select firstOnly locAVASalesLineBackOrderTmp
            where locAVASalesLineBackOrderTmp.SalesLineRefRecId == locSalesLine.RecId;

            if(     locAVASalesLineBackOrderTmp.RecId
                &&  locAVASalesLineBackOrderTmp.KCS_SOCPickingReleaseIndicator  ==  NoYes::Yes)
            {
                locAVASalesLineBackOrderTmp.KCS_SOCPickingReleaseIndicator = NoYes::No;
                locAVASalesLineBackOrderTmp.update();
            }
            if(     locSalesLine.RecId
                &&  locSalesLine.KCS_SOCPickingReleaseIndicator ==  NoYes::Yes)
            {
                locSalesLine.KCS_SOCPickingReleaseIndicator = NoYes::No;
                locSalesLine.update();

                locSalesLine.avaItemSetSalesLineSetKCS_SOCPickingReleaseIndicator();

                locSalesLine.avaUpdateSalesTableKCS_PickingReleaseIndicator();

                locGetSalesLinesFromDB = true;
            }
            if(releaseRevokeReservations && locSalesLine.reservedPhysical())
            {
                locInventQty = locSalesLine.qtyMarked();
                if(locInventQty <= 0)   // check marking
                {
                    locSalesLine.avaReserveSalesLine(locSalesLine, locSalesLine.reservedPhysical(), true); // unreserve qty
                    ttsbegin;
                    locSalesLine.selectForUpdate(true);
                    locSalesLine.ShippingDateConfirmed  = dateNull();
                    locSalesLine.ReceiptDateConfirmed   = dateNull();
                    locSalesLine.update();
                    ttscommit;
                    locGetSalesLinesFromDB = true;

                    if(locSalesLine.AVAItemSetComponent)
                    {
                        locSalesLineItemSet = locSalesLine.avaItemSetSalesLine();
                    }
                    else
                    {
                        locSalesLineItemSet = null;
                    }
                }
            }
            if(locSalesLineItemSet)
            {
                ttsbegin;
                locSalesLineItemSet.selectForUpdate(true);
                locSalesLineItemSet.ShippingDateConfirmed  = dateNull();
                locSalesLineItemSet.ReceiptDateConfirmed   = dateNull();
                locSalesLineItemSet.update();
                ttscommit;

                while select locSalesLineItemSetComponent
                where   locSalesLineItemSetComponent.AVAItemSetParent   == locSalesLineItemSet.InventTransId
                    &&  locSalesLineItemSetComponent.InventTransId      != locSalesLine.InventTransId
                {
                    select firstOnly locAVASalesLineBackOrderTmp
                    where locAVASalesLineBackOrderTmp.SalesLineRefRecId == locSalesLineItemSetComponent.RecId;

                    if(     locAVASalesLineBackOrderTmp.RecId
                        &&  locAVASalesLineBackOrderTmp.KCS_SOCPickingReleaseIndicator  ==  NoYes::Yes)
                    {
                        locAVASalesLineBackOrderTmp.KCS_SOCPickingReleaseIndicator = NoYes::No;
                        locAVASalesLineBackOrderTmp.update();
                    }
                    if(releaseRevokeReservations && locSalesLineItemSetComponent.reservedPhysical())
                    {
                        locInventQty = locSalesLineItemSetComponent.qtyMarked();
                        if(locInventQty <= 0)   // check marking
                        {
                            locSalesLineItemSetComponent.avaReserveSalesLine(locSalesLineItemSetComponent, locSalesLineItemSetComponent.reservedPhysical(), true); // unreserve qty
                            ttsbegin;
                            locSalesLineItemSetComponent.selectForUpdate(true);
                            locSalesLineItemSetComponent.ShippingDateConfirmed  = dateNull();
                            locSalesLineItemSetComponent.ReceiptDateConfirmed   = dateNull();
                            locSalesLineItemSetComponent.update();
                            ttscommit;
                            locSalesLineItemSetComponent.avaItemSetSalesLineSetKCS_SOCPickingReleaseIndicator();
                            locGetSalesLinesFromDB = true;
                        }
                    }
                }
                locSalesLineItemSet.avaUpdateSalesTableKCS_PickingReleaseIndicator();
            }
        }
        ttscommit;
    }

    if(locGetSalesLinesFromDB == true)
    {
        SalesLine_DS.research(true);

        element.refreshCallerForm();
    }

    return retVal;
}

/// <summary>
///    AVA <c>handleTmpTableChanges</c> method.
/// </summary>
private void handleTmpTableChanges()
{
    frmApprovalSaveOpenChanges = true;  // "Änderungen speichern"

    element.processTmpTablePositions();

    if(frmApprovalSaveOpenChanges)      // "Änderungen speichern"
    {
        AVASalesLineBackOrderTmp_DS.refresh();
        SalesLine_DS.reSearch(true);
    }

    frmApprovalSaveOpenChanges              = false; // "Änderungen speichern"
    frmReleaseForShipmentSaveWhenClosing    = false;

    this.resetApprovalFlags();
}

/// <summary>
///    AVA <c>resetApprovalFlags</c> method.
/// </summary>
private void resetApprovalFlags()
{
    frmAVAStockAvailability             = AVAStockAvailability::Unknown;

    frmApprovalUnmarkUnreserveSelected  = false;    // "Aufheben"
    frmApprovalReserveSelected          = false;    // "Reservieren"
    frmApprovalMarkAvailable            = false;    // "Verfügbare markieren" - Grün markieren
    frmReleaseFunctionsShippingDate     = false;
    frmReleaseFunctionsReservations     = false;
    frmReleaseFunctionReleaseMarked     = false;    // "Teilfreigabe"
    frmReleaseFunctionReleaseAll        = false;    // "Komplettfreigabe"
    frmReleasePosition                  = false;    // "Positionsfreigabe"
    frmApprovalSaveOpenChanges          = false;    // "Änderungen speichern"

    frmBlockReservations                = false;    // block reservation
}

/// <summary>
///    AVA <c>afterAVASalesLineBackOrderReservation</c> method.
/// </summary>
/// <param name="_avaSalesLineBackOrderTmp">
///    <c>AVASalesLineBackOrderTmp</c> as type
/// </param>
void afterAVASalesLineBackOrderReservation(AVASalesLineBackOrderTmp _avaSalesLineBackOrderTmp)
{
    SaLesLine                   locSalesLine;
    SaLesLine                   locItemSetSalesLineSearch;
    AVASalesLineBackOrderTmp    locAVASalesLineBackOrderTmpBase;
    AVASalesLineBackOrderTmp    locAVASalesLineBackOrderTmp;
    //InventTransId               locInventTransIdSearch;
    real                        locFactor;

    element.resetApprovalFlags();

    frmReleasePosition                  = true;    // "Positionsfreigabe"
    frmBlockReservations                = true;    // reservation done so block reservations

    //AVASalesLineBackOrderTmp_DS.findRecord(_avaSalesLineBackOrderTmp); // deprecated
    AVASalesLineBackOrderTmp_DS.positionToRecord(_avaSalesLineBackOrderTmp);
    //locAVASalesLineBackOrderTmpBase = AVASalesLineBackOrderTmp_DS.cursor();
    locSalesLine                    = _avaSalesLineBackOrderTmp.salesLine();
    locAVASalesLineBackOrderTmp     = _avaSalesLineBackOrderTmp.data();
    element.processTmpTablePositions(locAVASalesLineBackOrderTmp);

    if(locSalesLine.AVAItemSetComponent)
    {
        while select AVASalesLineBackOrderTmp
        {
            locAVASalesLineBackOrderTmpBase = AVASalesLineBackOrderTmp;
            locItemSetSalesLineSearch       = locAVASalesLineBackOrderTmpBase.salesLine();
            locAVASalesLineBackOrderTmp     = locAVASalesLineBackOrderTmpBase.data();

            if(     locItemSetSalesLineSearch.AVAItemSetParent  == locSalesLine.AVAItemSetParent
                &&  locItemSetSalesLineSearch.InventTransId     != locSalesLine.InventTransId   )
            {
                ttsbegin;
                AVASalesLineBackOrderTmp.selectForUpdate(true);
                AVASalesLineBackOrderTmp.KCS_SOCPickingReleaseIndicator = NoYes::Yes;
                AVASalesLineBackOrderTmp.Processed                      = true;
                //locFactor                                               = locSalesLine.AVAItemSetSerie  * locItemSetSalesLineSearch.AVAItemSetCompQtyPerSerie / minOne(locSalesLine.AVAItemSetCompQtyPerSerie) / minOne(locItemSetSalesLineSearch.AVAItemSetSerie);
                //AVASalesLineBackOrderTmp.SalesQtyPossible               = _avaSalesLineBackOrderTmp.SalesQtyPossible * locFactor;
                //AVASalesLineBackOrderTmp.SalesQtyEffective              = _avaSalesLineBackOrderTmp.SalesQtyEffective * locFactor;
                AVASalesLineBackOrderTmp.update();
                ttscommit;

                element.resetApprovalFlags();

                frmReleasePosition                  = true;    // "Positionsfreigabe"
                frmBlockReservations                = true;    // reservation done so block reservations

                element.processTmpTablePositions(locAVASalesLineBackOrderTmp);
                // AVASalesLineBackOrderTmp_ds.findRecord(locAVASalesLineBackOrderTmp); // deprecated
                AVASalesLineBackOrderTmp_ds.positionToRecord(locAVASalesLineBackOrderTmp);
            }
        }
    }
    /*
    SalesLine_DS.reSearch(true);
    AVASalesLineBackOrderTmp_DS.refresh();
    */
}

