/// <summary>
///    AVA <c>tmpReleaseIndicatorModified</c> method.
/// </summary>
/// <param name="_initialStatus">
///    <c>boolean</c> as type
/// </param>
/// <returns>
///    <c>boolean</c> as return value
/// </returns>
public boolean tmpReleaseIndicatorModified(boolean _initialStatus)
{
    boolean                             retVal;

    FormDataSource                      locAVASalesLineBackOrderTmpDS;
    AVASalesLineBackOrderTmp            locAVASalesLineBackOrderTmp;
    AVASalesLineBackOrderTmp            locAVASalesLineBackOrderTmpCursor;
    FormDataSource                      locSalesLineDS;
    SalesLine                           locSalesLine;
    SalesLine                           locSalesLineCursor;
    AVAStockAvailability                locAVAStockAvailability;
    boolean                             locSalesLineChanged;
    boolean                             locCheckFailed;
    boolean                             locItemSetHandling;
    boolean                             locIndicatorPossible2Set;

    Args                                dialogArgs;
    MenuFunction                        dialogMenuFunction;

    boolean                             locItemSetComponentsReleasable;
    KCS_SOCPickingReleaseIndicator      locKCS_SOCPickingReleaseIndicator;
    AVASalesLineBackOrderTmp            locAVASalesLineBackOrderTmpSearch;
    SalesLine                           locSalesLineSearch;
    AVAStockAvailability                locAVAStockAvailabilitySearch;
    str                                 locTmpStr;

    // internal functions
    void checkShippingDateConfirmed()
    {
        boolean checkValue;

        if(     locSalesLine.ShippingDateConfirmed  != dateNull()
            ||  frmSalesShippingDateConfirmed       != dateNull()   )
        {
            checkValue = true;
        }
        locIndicatorPossible2Set = locIndicatorPossible2Set && checkValue;
    }

    void unSetPickingReleaseIndicator(boolean _setSalesQtys = false)
    {
        ttsBegin;
        locAVASalesLineBackOrderTmpCursor.selectForUpdate(true);
        if(_setSalesQtys)
        {
            locAVASalesLineBackOrderTmpCursor.SalesQtyPossible    = 0;
            locAVASalesLineBackOrderTmpCursor.SalesQtyEffective   = 0;
        }
        locAVASalesLineBackOrderTmpCursor.KCS_SOCPickingReleaseIndicator = NoYes::No;
        locAVASalesLineBackOrderTmpCursor.update();
        ttsCommit;

        // set local Indicator to avoid further marking
        locKCS_SOCPickingReleaseIndicator   = locAVASalesLineBackOrderTmpCursor.KCS_SOCPickingReleaseIndicator;

        locAVASalesLineBackOrderTmp         = locAVASalesLineBackOrderTmpCursor.data();
    }

    //init variables
    retVal                                  = _initialStatus;

    locSalesLineDS                          = element.SalesLine_DS;
    locSalesLineCursor                      = locSalesLineDS.cursor();
    locSalesLine                            = locSalesLineCursor.data();
    element.setAVASalesLineBackOrderTmpCursorToSalesLine();
    locAVASalesLineBackOrderTmpDS           = element.AVASalesLineBackOrderTmp_DS;
    locAVASalesLineBackOrderTmpCursor       = locAVASalesLineBackOrderTmpDS.cursor();
    locAVASalesLineBackOrderTmp             = locAVASalesLineBackOrderTmpCursor.data();
    locAVAStockAvailability                 = locSalesLine.avaGetStockAvailablity();
    locItemSetHandling                      = locSalesLine.AVAItemSet || locSalesLine.AVAItemSetComponent;
    locKCS_SOCPickingReleaseIndicator       = locAVASalesLineBackOrderTmp.KCS_SOCPickingReleaseIndicator;


    this.setShippingDateConfirmedFormValues();

    if(locKCS_SOCPickingReleaseIndicator)
    {
        locIndicatorPossible2Set = true;

        switch(locAVASalesLineBackOrderTmp.AVAStockAvailability)
        {
            case AVAStockAvailability::Available:
            case AVAStockAvailability::PartitialAvailable:
            case AVAStockAvailability::IndividualRequired:
                checkShippingDateConfirmed();
                if(!locIndicatorPossible2Set)
                {
                    locCheckFailed = this.checkFailedShippingDateConfirmed();
                    unSetPickingReleaseIndicator();
                }
                break;

            case AVAStockAvailability::NotAvailable:
                checkShippingDateConfirmed();
                break;
        }
    }
    else
    {
        switch(locAVASalesLineBackOrderTmp.AVAStockAvailability)
        {
            case AVAStockAvailability::PartitialAvailable:
                unSetPickingReleaseIndicator(true);
                break;
        }
    }

    if(locKCS_SOCPickingReleaseIndicator)
    {
        switch(locAVASalesLineBackOrderTmp.AVAStockAvailability)
        {
            case AVAStockAvailability::Available:
                if(locItemSetHandling)
                {
                    if(locSalesLine.AVAItemSetComponent)
                    {
                        if(     locSalesLine.KCS_SOCPickingReleaseIndicator == NoYes::No
                            &&  locKCS_SOCPickingReleaseIndicator           == NoYes::Yes   )
                        {
                            locItemSetComponentsReleasable = true;
                            // check availability
                            while select AVASalesLineBackOrderTmp
                            {
                                locAVASalesLineBackOrderTmpSearch   = AVASalesLineBackOrderTmp;
                                locSalesLineSearch                  = locAVASalesLineBackOrderTmpSearch.SalesLine();

                                if(     locSalesLineSearch.RecId
                                    &&  locSalesLineSearch.AVAItemSetComponent
                                    &&  locSalesLineSearch.AVAItemSetParent     == locSalesLine.AVAItemSetParent
                                    &&  locSalesLineSearch.InventTransId        != locSalesLine.InventTransId      )
                                {
                                    locAVAStockAvailabilitySearch = locSalesLineSearch.avaGetStockAvailablity();

                                    if(locAVAStockAvailabilitySearch != AVAStockAvailability::Available)
                                    {
                                        locItemSetComponentsReleasable = false;
                                    }
                                }
                            }
                        }
                    }
                }
                /*
                else
                {
                    locAVASalesLineBackOrderTmp.KCS_SOCPickingReleaseIndicator = NoYes::Yes;
                }
                */
                break;

            case AVAStockAvailability::PartitialAvailable:
                if(locIndicatorPossible2Set)
                {
                    dialogArgs          = new Args();
                    dialogArgs.record(locAVASalesLineBackOrderTmpCursor);
                    dialogArgs.caller(element);
                    dialogMenuFunction  = new MenuFunction(menuItemDisplayStr(AVASalesLineBackOrderReservation), MenuItemType::Display);
                    dialogMenuFunction.run(dialogArgs);
                    locSalesLineChanged = true;
                }
                else
                {
                    unSetPickingReleaseIndicator();
                }
                break;

            case AVAStockAvailability::NotAvailable:
                //locCheckFailed      = checkFailed("@NDX:NXAReleaseForShipmentNotPossibleNoStock");
                //unSetPickingReleaseIndicator();
                if(locIndicatorPossible2Set)
                {
                    if(locSalesLine.reservedPhysicalInSalesUnit() > 0)
                    {
                        locIndicatorPossible2Set = true;
                    }
                    if(     locSalesLine.AVAItemSetComponent
                        &&  locIndicatorPossible2Set        )
                    {
                        // check availability
                        while select AVASalesLineBackOrderTmp
                        {
                            locAVASalesLineBackOrderTmpSearch   = AVASalesLineBackOrderTmp;
                            locSalesLineSearch                  = locAVASalesLineBackOrderTmpSearch.SalesLine();

                            if(     locSalesLineSearch.RecId
                                    &&  locSalesLineSearch.AVAItemSetComponent
                                    &&  locSalesLineSearch.AVAItemSetParent     == locSalesLine.AVAItemSetParent
                                    &&  locSalesLineSearch.InventTransId        != locSalesLine.InventTransId      )
                            {
                                locAVAStockAvailabilitySearch = locSalesLineSearch.avaGetStockAvailablity();

                                if(     locAVAStockAvailabilitySearch       == AVAStockAvailability::Available
                                    ||  (   locAVAStockAvailabilitySearch   == AVAStockAvailability::NotAvailable
                                        &&  locSalesLineSearch.reservedPhysicalInSalesUnit() > 0                    )   )
                                {
                                    locIndicatorPossible2Set = locIndicatorPossible2Set;
                                }
                                else
                                {
                                    locIndicatorPossible2Set = false;
                                }
                            }
                        }

                        if(locIndicatorPossible2Set)
                        {
                            ttsbegin;
                            while select forupdate AVASalesLineBackOrderTmp
                            {
                                locAVASalesLineBackOrderTmpSearch  = AVASalesLineBackOrderTmp;
                                locSalesLineSearch                 = locAVASalesLineBackOrderTmpSearch.SalesLine();

                                if(     locSalesLineSearch.RecId
                                    &&  locSalesLineSearch.AVAItemSetComponent
                                    &&  locSalesLineSearch.AVAItemSetParent == locSalesLine.AVAItemSetParent  )
                                {
                                    AVASalesLineBackOrderTmp.KCS_SOCPickingReleaseIndicator = locKCS_SOCPickingReleaseIndicator;
                                    AVASalesLineBackOrderTmp.update();
                                }
                            }
                            ttscommit;
                        }
                    }
                }
                if(locSalesLine.reservedPhysicalInSalesUnit() == 0)
                {
                    locTmpStr = strFmt( "@NDX:NXAP1P2needsReservationForShipmentRelease",
                                            SysLabel::labelId2String(literalStr("@NDX:NXAStockAvailability"), frmLanguageId),
                                            SysLabel::labelId2String(literalStr("@NDX:NXAStockAvailabilityNotAvailable"), frmLanguageId));
                    checkFailed(locTmpStr);
                    unSetPickingReleaseIndicator();
                }
               break;

            case AVAStockAvailability::IndividualRequired:
                unSetPickingReleaseIndicator();
                break;

            case AVAStockAvailability::Unknown:
                unSetPickingReleaseIndicator();
                break;

            case AVAStockAvailability::InCycleCount:
                unSetPickingReleaseIndicator();
                break;
        }
    }
    else
    {
        switch(locAVASalesLineBackOrderTmp.AVAStockAvailability)
        {
            case AVAStockAvailability::PartitialAvailable:
                unSetPickingReleaseIndicator(true);
                break;
        }
    }

    if(locSalesLine.AVAItemSetComponent)
    {
        if(     (locItemSetComponentsReleasable == true     && locKCS_SOCPickingReleaseIndicator == NoYes::Yes)
            ||  (locItemSetComponentsReleasable == false    && locKCS_SOCPickingReleaseIndicator == NoYes::No)  )
        {
            /*
            ttsbegin;
            while select forupdate AVASalesLineBackOrderTmp
            {
                locAVASalesLineBackOrderTmpSearch  = AVASalesLineBackOrderTmp;
                locSalesLineSearch                 = locAVASalesLineBackOrderTmpSearch.SalesLine();

                if(     locSalesLineSearch.RecId
                        &&  locSalesLineSearch.AVAItemSetComponent
                        &&  locSalesLineSearch.AVAItemSetParent == locSalesLine.AVAItemSetParent  )
                {
                    AVASalesLineBackOrderTmp.KCS_SOCPickingReleaseIndicator = locKCS_SOCPickingReleaseIndicator;
                    AVASalesLineBackOrderTmp.update();
                }
            }
            ttscommit;
            //AVASalesLineBackOrderTmp_DS.refresh();
            SalesLine_DS.ReSearch(true);
            */
            this.setPickingReleaseIndicatorSingleOrItemSets(locSalesLine, locKCS_SOCPickingReleaseIndicator);
        }
    }

    if(locSalesLineChanged)
    {
        locSalesLineDS.reread();
        locSalesLineDS.refresh();
    }
    locAVASalesLineBackOrderTmpDS.refresh();

    return retVal;
}

/// <summary>
///     AVA <c>setPickingReleaseIndicatorSingleOrItemSets</c> method.
///     AVA - Schneider 13.06.2024
/// </summary>
/// <param name="_salesLine">
///     <c>SalesLine</c> as type
/// </param>
/// <param name="_kcs_SOCPickingReleaseIndicator">
///     <c>KCS_SOCPickingReleaseIndicator</c> as type
/// </param>
void setPickingReleaseIndicatorSingleOrItemSets(SalesLine                       _salesLine, 
                                                KCS_SOCPickingReleaseIndicator  _kcs_SOCPickingReleaseIndicator = NoYes::No )
{
    AVASalesLineBackOrderTmp    locAVASalesLineBackOrderTmpSearch;
    SalesLine                   locSalesLineSearch;
    boolean                     locUpdated;

    if(_salesLine.AVAItemSetComponent)
    {
        ttsbegin;
        while select forupdate AVASalesLineBackOrderTmp
        {
            locAVASalesLineBackOrderTmpSearch  = AVASalesLineBackOrderTmp;
            locSalesLineSearch                 = locAVASalesLineBackOrderTmpSearch.SalesLine();

            if(     locSalesLineSearch.RecId
                &&  locSalesLineSearch.AVAItemSetComponent
                &&  locSalesLineSearch.AVAItemSetParent                     == _salesLine.AVAItemSetParent  )
                //&&  AVASalesLineBackOrderTmp.KCS_SOCPickingReleaseIndicator != _kcs_SOCPickingReleaseIndicator  )
            {
                AVASalesLineBackOrderTmp.KCS_SOCPickingReleaseIndicator = _kcs_SOCPickingReleaseIndicator;
                AVASalesLineBackOrderTmp.update();
                locUpdated = true;
            }
        }
        ttscommit;
    }
    else if(_salesLine.RecId)
    {
        ttsbegin;
        while select forupdate AVASalesLineBackOrderTmp
        {
            locAVASalesLineBackOrderTmpSearch  = AVASalesLineBackOrderTmp;
            locSalesLineSearch                 = locAVASalesLineBackOrderTmpSearch.SalesLine();

            if(     locSalesLineSearch.RecId
                &&  AVASalesLineBackOrderTmp.SalesLineRefRecId              == _salesLine.RecId )
                //&&  AVASalesLineBackOrderTmp.KCS_SOCPickingReleaseIndicator != _kcs_SOCPickingReleaseIndicator  )
            {
                AVASalesLineBackOrderTmp.KCS_SOCPickingReleaseIndicator = _kcs_SOCPickingReleaseIndicator;
                AVASalesLineBackOrderTmp.update();
                locUpdated = true;
            }
        }
        ttscommit;
    }

    if(locUpdated)
    {
        //AVASalesLineBackOrderTmp_DS.refresh();
        SalesLine_DS.ReSearch(true);
    }
}

/// <summary>
///    AVA <c>checkItemSetRelease</c> method.
/// </summary>
/// <param name="_salesLine">
///    <c>SalesLine</c> as type
/// </param>
/// <param name="_singleAVASalesLineBackOrderTmp">
///    <c>AVASalesLineBackOrderTmp</c> as type
/// </param>
/// <returns>
///    <c>boolean</c> as return value
/// </returns>
private boolean checkItemSetComponentReleasable(SalesLine                   _salesLine,
                                                AVASalesLineBackOrderTmp    _singleAVASalesLineBackOrderTmp = null)
{
    boolean                     retVal;

    AVASalesLineBackOrderTmp    locAVASalesLineBackOrderTmp;
    FormDatasource              locSalesLineDS;
    SalesLine                   locSalesLine;
    AVAStockAvailability        locAVAStockAvailability;

    locAVASalesLineBackOrderTmp = _singleAVASalesLineBackOrderTmp;
    locAVAStockAvailability     = AVAStockAvailability::Available;

    if(_salesLine.AVAItemSetComponent)
    {
        locSalesLineDS  = element.SalesLine_DS;
        locSalesLine    = SalesLine_DS.getFirst() as SalesLine;
        while(locSalesLine)
        {
            if(     locAVAStockAvailability         == AVAStockAvailability::Available
                &&  locSalesLine.AVAItemSetComponent
                &&  locSalesLine.AVAItemSetParent   == _salesLine.AVAItemSetParent
                &&  locSalesLine.RecId              != _salesLine.RecId                 )
            {
                locAVAStockAvailability = locSalesLine.avaGetStockAvailablity();
            }
            locSalesLine = SalesLine_DS.getNext() as SalesLine;
        }

        if(locAVAStockAvailability == AVAStockAvailability::Available)
        {
            retVal = true;
        }
    }
    return retVal;
}

