/// <summary>
///     AVA <c>setAVASalesLineBackOrderTmpCursorToSalesLine</c> method.
///     AVA - Schneider 28.06.2024
/// </summary>
public void setAVASalesLineBackOrderTmpCursorToSalesLine()
{
    FormDatasource              locSalesLineDS;
    SalesLine                   locSalesLine;
    FormDatasource              locAVASalesLineBackOrderTmpDS;
    AVASalesLineBackOrderTmp    locAVASalesLineBackOrderTmp;
    AVASalesLineBackOrderTmp    locAVASalesLineBackOrderTmpSearch;

    locSalesLineDS                      = SalesLine_DS;
    locSalesLine                        = locSalesLineDS.cursor();
    locAVASalesLineBackOrderTmpDS       = AVASalesLineBackOrderTmp_DS;
    locAVASalesLineBackOrderTmp         = locAVASalesLineBackOrderTmpDS.cursor();
    locAVASalesLineBackOrderTmpSearch   = locAVASalesLineBackOrderTmp;

    if(     locSalesLine.RecId
        &&  locSalesLine.InventTransId != locAVASalesLineBackOrderTmp.InventTransId  )
    {
        select firstonly AVASalesLineBackOrderTmp
        where AVASalesLineBackOrderTmp.InventTransId == locSalesLine.InventTransId;

        locAVASalesLineBackOrderTmpSearch = AVASalesLineBackOrderTmp;
        //AVASalesLineBackOrderTmp_DS.positionToRecord(locAVASalesLineBackOrderTmpSearch);
    }

    frmSalesLine                = locSalesLine;
    frmAVASalesLineBackOrderTmp = locAVASalesLineBackOrderTmp;
}

