/// <summary>
///    AVA <c>active</c> method.
/// </summary>
/// <returns>
///    <c>int</c> as return value
/// </returns>
public int active()
{
    int                     retVal;
    QueryBuildDataSource    inventSumQBDS;
    SalesLine               locSalesLine;

    FormDataSource          locSalesTableDS;
    SalesTable              locSalesTable;

    retVal = super();

    locSalesTableDS = SalesTable_DS;
    locSalesTable   = locSalesTableDS.cursor();
    locSalesLine    = this.cursor();

    GridInfo_GrossWeight.realValue(0.0);

    if(locSalesTableDS)
    {
        locSalesTable   = locSalesTableDS.cursor();

        GridInfo_GrossWeight.realValue(locSalesTable.avaGetGrossWeightRemaining());
    }

    inventSumQBDS = InventSum_DS.query().dataSourceName(InventSum_DS.name());
    SysQuery::findOrCreateRange(inventSumQBDS, fieldNum(InventSum, InventSiteId)).value(queryValue(locSalesLine.inventDim().InventSiteId));

    if(frmAVASalesLineBackOrderTmpResearch)
    {
        AVASalesLineBackOrderTmp_DS.research();
        frmAVASalesLineBackOrderTmpResearch = false;
    }

    //element.cursorInfo('SalesLine_DS Active');

    return retVal;
}

/// <summary>
///    AVA <c>displayOption</c> method.
/// </summary>
/// <param name="_record">
///    <c>Common</c> as type
/// </param>
/// <param name="_options">
///    <c>FormRowDisplayOption</c> as type
/// </param>
public void displayOption(Common _record, FormRowDisplayOption _options)
{
    SalesLine   locSalesLine;

    int         locItemSetColor;
    int         locItemSetColorExpanded;
    int         locItemSetColorComponent;

    super(_record, _options);

    locSalesLine                    = _record;

    if(element.frmAVAItemSetParameters.RecId)
    {
        locItemSetColor             = element.frmAVAItemSetParameters.ItemSetBGColor;
        locItemSetColorExpanded     = element.frmAVAItemSetParameters.ItemSetBGColorExpanded;
        locItemSetColorComponent    = element.frmAVAItemSetParameters.ItemSetBGColorComponent;
    }
    else
    {
        locItemSetColor             = 16744576; // FF8080 or 255,128,128 or WinAPI::RGB2int(255, 128, 128)    // light red
        locItemSetColorExpanded     = 65505;    // 00FFE1 or 0,255,255  or WinAPI::RGB2int(0, 255, 255)       // turquoise
        locItemSetColorComponent    = 8454118;  // 80FFE6 or 128,255,255  or WinAPI::RGB2int(128, 255, 255)   // light turquoise
    }

    if(     locSalesLine.AVAItemSetExpanded
    &&  locItemSetColorExpanded                 )
    {
        _options.backColor(locItemSetColorExpanded);
    }
    else if(    locSalesLine.AVAItemSet
        &&  locItemSetColor                 )
    {
        _options.backColor(locItemSetColor);
    }
    else if(    locSalesLine.AVAItemSetParent
        &&  locItemSetColorComponent            )
    {
        _options.backColor(locItemSetColorComponent);
    }
    /*
    else
    {
    _options.clearBackColor();
    }
    */
}

/// <summary>
///     AVA <c>linkActive</c> method.
///     AVA - Schneider 28.06.2024
/// </summary>
public void linkActive()
{
    SalesId     locSalesId;
    SalesTable  locSalesTable;
    boolean     locRebuildTmpTableData;

    // Is form called with a record
    if (element.args() && element.args().record())
    {
        switch (element.args().dataset())
        {
            // Is the form called from the activities form
            case tableNum(SalesTable) :
                locSalesTable   = element.args().record();
                locSalesId      = locSalesTable.SalesId;

                if(     locSalesTable.RecId 
                    &&  frmSalesId != ''
                    &&  frmSalesId != locSalesId    )
                {
                    frmSalesTable                       = locSalesTable;
                    frmSalesId                          = locSalesId;
                    locRebuildTmpTableData              = true;
                    frmAVASalesLineBackOrderTmpResearch = true;
                }
                break;
        }
    }

    super();

    if(locRebuildTmpTableData)
    {
        element.initQueryRanges();

        GridInfo_GrossWeight.realValue(0.0);

        if(frmSalesId)
        {
            AVASalesLineBackOrderTmp.linkPhysicalTableInstance(element.createSalesLineTmpTableData());
            /*
            // already linked, linking anew causes error
            element.createSalesLineTmpTableData();
            AVASalesLineBackOrderTmp = element.createSalesLineTmpTableData();
            */
            if(locSalesTable.RecId)
            {
                GridInfo_GrossWeight.realValue(locSalesTable.avaGetGrossWeightRemaining());
            }
            // default as designed
            AVASalesLineBackOrderTmp_DS.query().dataSourceTable(tableNum(AVASalesLineBackOrderTmp)).joinMode(JoinMode::InnerJoin);
        }
        else
        {
            AVASalesLineBackOrderTmp_DS.query().dataSourceTable(tableNum(AVASalesLineBackOrderTmp)).joinMode(JoinMode::OuterJoin);
        }

        SalesLine_ds.executeQuery();
    }
}

