public void executeQuery()
{
    QueryBuildDataSource    locQDBS;
    locQDBS = this.query().dataSourceTable(tableNum(InventSum));

    element.inventDimSetupObject().modifyQuery(inventSum_DS, inventDim_Invent_ds);
    if (inventSum_DS.queryRun() && inventSum_DS.queryRun().query())
    {
        element.inventDimSetupObject().modifyQueryBasedOnDatasourceName(
                inventSum_DS.queryRun().query(),
                inventSum_DS.name(),
                inventDim_Invent_ds);
    }

    super();

    SysQuery::findOrCreateRange(locQDBS, fieldNum(InventSum, Closed)).value(queryValue(NoYes::No));
    SysQuery::findOrCreateRange(locQDBS, fieldNum(InventSum, ClosedQty)).value(queryValue(NoYes::No));
    SysQuery::findOrCreateRange(locQDBS, fieldNum(InventSum, ClosedQty)).enabled(false);
}

