/// <summary>
///    AVA <c>modified</c> method.
/// </summary>
/// <returns>
///    <c>boolean</c> as return value
/// </returns>
public boolean modified()
{
    boolean                     ret;
    FormRealControl             locFormRealControl;
    KCS_TonnageCalcedData       locKCS_TonnageCalcedData;
    Percent                     locPercent;

    SalesShippingDateConfirmed  tmpValueSSDC;
    SalesReceiptDateConfirmed   tmpValueSRDC;
    SalesTable                  locSalesTable;

    SalesCalcAvailableDlvDates  calcAvailableDlvDates;
    SalesCalcAvailableDlvDates_SalesTable calcAvailableDlvDates_ST;

    ret = super();

    locSalesTable.clear();
    //locSalesTable = frmSalesTable;
    buf2Buf(frmSalesTable, locSalesTable);
    locSalesTable.ShippingDateRequested = ReleasForShipment_ShippingDateConfirmed.dateValue();
    locSalesTable.ReceiptDateRequested  = dateNull();

    /* Alternnative
    locSalesTable.modifiedField(fieldNum(SalesTable, ShippingDateRequested));
    tmpValueSSDC                = ReleasForShipment_ShippingDateConfirmed.dateValue(locSalesTable.ShippingDateRequested);
    if(frmSalesTable.RecId && frmSalesTable.AVAPrintReceiptDate == NoYes::Yes)
    {
        tmpValueSRDC            = ReleasForShipment_ReceiptDateConfirmed.dateValue(locSalesTable.ReceiptDateRequested);
    }
    */

    calcAvailableDlvDates       = SalesCalcAvailableDlvDates::newCommonSalesDlvDateType(locSalesTable, fieldNum(SalesTable, ShippingDateRequested));
    calcAvailableDlvDates_ST    = calcAvailableDlvDates as SalesCalcAvailableDlvDates_SalesTable;
    calcAvailableDlvDates_ST.modifiedField(locSalesTable, true, false, true);
    tmpValueSSDC                = ReleasForShipment_ShippingDateConfirmed.dateValue(calcAvailableDlvDates_ST.parmShippingDateAvailableSelected());
    if(tmpValueSSDC == dateNull())
    {
        tmpValueSSDC                = ReleasForShipment_ShippingDateConfirmed.dateValue(calcAvailableDlvDates_ST.parmShippingDateBestGuess());
    }
    if(frmSalesTable.RecId && frmSalesTable.AVAPrintReceiptDate == NoYes::Yes)
    {
        tmpValueSRDC            = ReleasForShipment_ReceiptDateConfirmed.dateValue(calcAvailableDlvDates_ST.parmReceiptDateAvailableSelected());
        if(tmpValueSRDC == dateNull())
        {
            tmpValueSRDC                = ReleasForShipment_ReceiptDateConfirmed.dateValue(calcAvailableDlvDates_ST.parmReceiptDateBestGuess());
        }
    }

    if(     tmpValueSRDC    != dateNull()
        &&  tmpValueSSDC    != dateNull()
        &&  tmpValueSRDC    < tmpValueSSDC   )
    {
        ReleasForShipment_ReceiptDateConfirmed.dateValue(tmpValueSSDC);
    }

    locKCS_TonnageCalcedData    = KCS_TonnageCalcedData::find(tmpValueSSDC, InventDim.InventSiteId);
    locPercent                  = locKCS_TonnageCalcedData.Percent;

    frmShipmentDateConfirmed    = tmpValueSSDC;
    locFormRealControl          = ReleasForShipment_ShipmentWorkload;
    if(locKCS_TonnageCalcedData.RecId)
    {
        ReleasForShipment_ShipmentWorkload.realValue(locPercent);

        locFormRealControl.colorScheme(FormColorScheme::RGB);
        if(locPercent < frmKCS_TonnageSetup.PercentWarning)
        {
            locFormRealControl.colorScheme(frmColorScheme);
            locFormRealControl.backgroundColor(frmBackgroundColor);             // orginal
            //locFormRealControl.colorScheme(FormColorScheme::RGB);
            //locFormRealControl.backgroundColor(WinAPI::RGB2int(0, 175, 63));    // green
        }
        else if(locPercent < 100)
        {
            locFormRealControl.colorScheme(FormColorScheme::RGB);
            locFormRealControl.backgroundColor(WinAPI::RGB2int(255, 175, 0));   // orange
        }
        else
        {
            locFormRealControl.colorScheme(FormColorScheme::RGB);
            locFormRealControl.backgroundColor(WinAPI::RGB2int(255, 0, 0));     // red
        }
    }
    else
    {
        ReleasForShipment_ShipmentWorkload.realValue(0.0);
        locFormRealControl.colorScheme(frmColorScheme);
        locFormRealControl.backgroundColor(frmBackgroundColor);             // orginal
    }

    return ret;
}

