/// <summary>
///    AVA <c>clicked</c> method.
/// </summary>
public void clicked()
{
    FormDataSource  locSalesLineDS;
    SalesLine       locSalesLine;
    SalesLine       locSalesLineSearch;
    FormDataSource  locInventSumDS;
    InventSum       locInventSum;
    FormDataSource  locInventDimDS;
    InventDim       locInventDim;
    FormDataSource  locInventDim_InventDS;
    InventDim       locInventDim_Invent;
    boolean         locChangedSalesLine;
    boolean         locChangedItemSet;
    SalesLine       locSalesLineBase;

    if(     inventDimFormSetup.parmDimParmVisible().InventSiteIdFlag        == NoYes::No
        ||  inventDimFormSetup.parmDimParmVisible().InventLocationIdFlag    == NoYes::No)
    {
        throw error("@NDX:NXAErrorMissedDimension");
    }

    super();

    locSalesLineDS          = element.SalesLine_DS;
    locSalesLine            = locSalesLineDS.cursor();

    locInventDimDS          = element.InventDim_DS;
    locInventDim            = locInventDimDS.cursor();

    locInventSumDS          = element.InventSum_DS;
    locInventSum            = locInventSumDS.cursor();

    locInventDim_InventDS   = element.InventDim_Invent_DS;
    locInventDim_Invent     = locInventDim_InventDS.cursor();

    locInventDim            = locSalesLine.inventDim();

    if(locSalesLine.avaCheckForTransferInventSiteAndLocation(locInventDim, locInventDim_Invent))
    {
        if(     locInventDim_Invent.InventSiteId
            &&  locInventDim_Invent.InventLocationId
            &&  locInventSum.AvailOrdered               ) // AvailPhysical)
        {
            if(     locInventDim.InventSiteId       != locInventDim_Invent.InventSiteId
                ||  locInventDim.InventLocationId   != locInventDim_Invent.InventLocationId)
            {
                ttsBegin;
                locInventDim.InventSiteId       = locInventDim_Invent.InventSiteId;
                locInventDim.InventLocationId   = locInventDim_Invent.InventLocationId;
                locInventDim                    = InventDim::findOrCreate(locInventDim);
                locSalesLine.InventDimId        = locInventDim.inventDimId;
                ///AVA/WEN/2025/10/27 AVA_013622_InventLocationWithFinDim
                locSalesLine.DefaultDimension = locSalesLine.mergeDimension(InventSite::find(locInventDim.InventSiteId).DefaultDimension, locSalesLine.DefaultDimension);
                ///AVA/WEN/2025/10/27 AVA_013622_InventLocationWithFinDim
                locSalesLine.selectForUpdate(true);
                locSalesLine.update();
                locChangedSalesLine             = true;

                if(locSalesLine.AVAItemSetComponent == NoYes::Yes)
                {
                    while select locSalesLineSearch
                        where   locSalesLineSearch.AVAItemSetParent == locSalesLine.AVAItemSetParent
                            &&  locSalesLineSearch.InventTransId    != locSalesLine.InventTransId
                    {
                        locInventDim                    = locSalesLineSearch.inventDim();
                        locInventDim.InventSiteId       = locInventDim_Invent.InventSiteId;
                        locInventDim.InventLocationId   = locInventDim_Invent.InventLocationId;
                        locInventDim                    = InventDim::findOrCreate(locInventDim);

                        locSalesLineSearch.InventDimId  = locInventDim.inventDimId;
                        locSalesLineSearch.selectForUpdate(true);
                        locSalesLineSearch.update();
                        locChangedItemSet               = true;
                    }
                    ///AVA/WEN/2025/10/27 AVA_013622_InventLocationWithFinDim
                    select forupdate firstonly locSalesLineBase where locSalesLineBase.InventTransId == locSalesLine.AVAItemSetParent;
                    locInventDim                    = locSalesLineBase.inventDim();
                    locInventDim.InventSiteId       = locInventDim_Invent.InventSiteId;
                    locInventDim.InventLocationId   = locInventDim_Invent.InventLocationId;
                    locInventDim                    = InventDim::findOrCreate(locInventDim);

                    locSalesLineBase.InventDimId  = locInventDim.inventDimId;
                    locSalesLineBase.DefaultDimension = locSalesLineBase.mergeDimension(InventSite::find(locInventDim.InventSiteId).DefaultDimension, locSalesLineBase.DefaultDimension);
                    locSalesLineBase.selectForUpdate(true);
                    locSalesLineBase.update();
                    ///AVA/WEN/2025/10/27 AVA_013622_InventLocationWithFinDim
                }
                ttsCommit;
            }
        }
    }
    if(locChangedItemSet)
    {
        locSalesLineDS.reread();
        locSalesLineDS.refresh();
        locInventDimDS.reread();
        locInventDimDS.refresh();
        locInventSumDS.reread();
        locInventSumDS.refresh();
        locInventDim_InventDS.reread();
        locInventDim_InventDS.refresh();
    }
    if(locChangedSalesLine)
    {
        locSalesLineDS.executeQuery();
        locSalesLineDS.refresh();
    }
}
